import{_ as t,o as d,c as o,a2 as c}from"./chunks/framework.D7EuCHIT.js";const m=JSON.parse('{"title":"主题与组件换肤","description":"","frontmatter":{},"headers":[],"relativePath":"plugins/theming.md","filePath":"plugins/theming.md","lastUpdated":1795360698000}'),a={name:"plugins/theming.md"};function r(i,e,l,n,h,s){return d(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="主题与组件换肤" tabindex="-1">主题与组件换肤 <a class="header-anchor" href="#主题与组件换肤" aria-label="Permalink to &quot;主题与组件换肤&quot;">​</a></h1><p>宿主组件的观感由 <code>ui.toml</code> 的配置表驱动，插件不需要重写绘制就能整体或局部换肤。所有表都可通过 <code>LYRA_INTERFACE_CONFIG</code>(4) 的 describe/write 读写，声明了 <code>config_tables</code> 的服务会消费对应表。</p><h2 id="调色板-theme-表" tabindex="-1">调色板：theme 表 <a class="header-anchor" href="#调色板-theme-表" aria-label="Permalink to &quot;调色板：theme 表&quot;">​</a></h2><p><code>theme</code> 服务（内置 <code>theme.builtin</code>，可被同名 capability 替换）声明 <code>config_tables = &quot;theme&quot;</code>。调色板是 light/dark 双套颜色，<code>follow_system</code>/<code>dark</code> 控制明暗，<code>transition_ms</code> 控制交叉淡入。</p><table tabindex="0"><thead><tr><th>键</th><th>语义</th></tr></thead><tbody><tr><td><code>light_surface</code>/<code>dark_surface</code></td><td>卡片/面板底色</td></tr><tr><td><code>light_ink</code>/<code>dark_ink</code></td><td>主文字色</td></tr><tr><td><code>light_secondary</code>/<code>dark_secondary</code></td><td>次要文字/图标色</td></tr><tr><td><code>light_action</code>/<code>dark_action</code></td><td>主按钮底色</td></tr><tr><td><code>light_action_ink</code>/<code>dark_action_ink</code></td><td>主按钮文字色</td></tr><tr><td><code>tint_light</code>/<code>tint_dark</code></td><td>封面染色强度（0..1，混入封面色到主题色）</td></tr><tr><td><code>status_*</code></td><td>状态栏面板的 luma/内边距/暗化参数</td></tr></tbody></table><p>写入示例（CONFIG write，key 为 <code>theme.dark_ink</code>）：插件可在设置页或自己的界面提供取色器，把用户选择写回对应键；宿主下一帧生效。</p><h2 id="组件级参数-geometry-player-shell-等表" tabindex="-1">组件级参数：geometry/player/shell 等表 <a class="header-anchor" href="#组件级参数-geometry-player-shell-等表" aria-label="Permalink to &quot;组件级参数：geometry/player/shell 等表&quot;">​</a></h2><p>调色板只管颜色。组件的尺寸、圆角、间距、字号在各自配置表：<code>geometry</code>（布局度量）、<code>player</code>（播放页）、<code>shell</code>（外壳/抽屉）、<code>dock</code>、<code>sheet</code>、<code>scroll</code>、<code>card_shadow</code>、<code>cover_fx</code> 等。完整键清单见<a href="/LyraPlayer-docs-site/config/reference/">配置参考</a>按表生成的页面（如 <code>/config/reference/ui-geometry</code>），每个键的类型与默认值以生成页为准。</p><h2 id="自绘组件取色" tabindex="-1">自绘组件取色 <a class="header-anchor" href="#自绘组件取色" aria-label="Permalink to &quot;自绘组件取色&quot;">​</a></h2><p>插件自绘界面需要当前生效色值时，用 <code>LYRA_INTERFACE_CONFIG</code> describe 读上述键的当前值（write 后 describe 返回新值）；明暗插值由宿主完成，插件读到的是表内配置值而非插值结果。需要实时主题色的场景目前没有专用只读接口，建议缓存 describe 结果并在配置 revision 变化时刷新。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><ul><li>改 <code>theme</code>/<code>geometry</code> 等表影响<strong>所有</strong>使用默认主题的组件，包括宿主默认 UI——插件应在自己的设置项里说明影响范围；</li><li>只想整体换一个&quot;样式&quot;（背景+配色一体）应使用 <code>LYRA_INTERFACE_STYLES</code>(3) 提供样式描述，由宿主样式选择器管理生命周期；</li><li><code>ui.toml</code> 是宿主配置文件，插件通过 CONFIG 接口写入的键仍受宿主 schema 校验，非法值被拒绝。</li></ul>',12)])])}const u=t(a,[["render",r]]);export{m as __pageData,u as default};
